  readonly isLoading$ = new BehaviorSubject<boolean>(false);
  readonly cartao$ = new BehaviorSubject<CartoesCreditoModel | null>(null);
  readonly contas$ = new BehaviorSubject<any[]>([]);

  constructor() {
    // reload contas whenever banco selection changes so select options are correct
    this.selectedBanco.selectedBancoId$.subscribe(id => {
      this.loadContas(id);
    });
  }

  private loadContas(bancoId: string | null): void {
    if (!bancoId) {
      this.contas$.next([]);
      return;
    }
    this.contasService.getAll(bancoId).subscribe({
      next: (dtos) => {
        try {
          const models = ContasMapper.toModelArray(dtos);
          this.contas$.next(models);
        } catch {
          this.contas$.next(dtos as any[]);
        }
      },
      error: () => this.contas$.next([])
    });
  }

  /**
   * Loads the card data by ID and updates the state accordingly.
   * @param id
   */
  loadData(id: string): void {
    this.isLoading$.next(true);

    this.service.getById(id).subscribe({
      next: (dto) => {
        const model = CartoesCreditoMapper.toModel(dto);
        this.cartao$.next(model);
        this.isLoading$.next(false);
      },
      error: (_err) => {
        this.notification.error('Falha ao carregar cartão');
        this.isLoading$.next(false);
        this.router.navigate(['/cartoes-credito']);
      }
    });
  }

  /**
   * Submits the updated card data to the service and handles the response.
   * Accepts partial update DTO; note that `saldoUtilizado` is intentionally excluded from updates.
   * @param id - The ID of the card being updated.
   * @param formData - The updated card data from the form.
   */
  submit(id: string, formData: CartoesCreditoUpdateDTO): void {
    this.isLoading$.next(true);

    // Helper to parse date strings (yyyy-MM-dd or other parseable formats) into {dia, mes, ano}
    const parseToParts = (raw?: string | null) => {
      if (!raw) return null;
      const isoMatch = String(raw).match(/^\s*(\d{4})-(\d{2})-(\d{2})\s*$/);
      if (isoMatch) {
        const ano = Number(isoMatch[1]);
        const mes = Number(isoMatch[2]);
        const dia = Number(isoMatch[3]);
        if (Number.isFinite(ano) && Number.isFinite(mes) && Number.isFinite(dia)) return { dia, mes, ano };
      }
      const d = new Date(String(raw));
      if (!isNaN(d.getTime())) return { dia: d.getDate(), mes: d.getMonth() + 1, ano: d.getFullYear() };
      return null;
    };

    // If periodo is included in the update payload, normalize its date fields
    if ((formData as any)?.periodo) {
      const rawInicio = (formData as any).periodo?.dataInicio;
      const rawFecho = (formData as any).periodo?.dataFim;
      const inicioParts = parseToParts(rawInicio);
      const fechoParts = parseToParts(rawFecho);
      if (!inicioParts || !fechoParts) {
        this.isLoading$.next(false);
        this.notification.error('Datas inválidas. Use o selector de datas para definir o período.');
        return;
      }
      (formData as any).periodo = { inicio: inicioParts, fecho: fechoParts };
    }

    this.service.update(id, formData).subscribe({
      next: () => {
        this.notification.success('Cartão atualizado com sucesso');
        this.isLoading$.next(false);
        this.router.navigate(['/cartoes-credito']);
      },
      error: (_err) => {
        this.notification.error('Falha ao atualizar cartão');
        this.isLoading$.next(false);
      }
    });
  }
}

import { Injectable, inject } from '@angular/core';
import { BehaviorSubject, forkJoin } from 'rxjs';
import { CartoesCreditoService } from '../../services/cartoes-credito.service';
import { NotificationService } from '../../../../services/notification.service';
import { CartoesCreditoModel } from '../../models/cartoes-credito.model';
import { CartoesCreditoMapper } from '../../mappers/cartoes-credito.mapper';
import { AuthService } from '../../../auth/services/auth.service';
import { SelectedBancoService } from '../../../../services/selected-banco.service';
import { ExtratoCartaoDTO } from '../../dto/cartoes-credito.dto';
import { formatEntityReference as formatEntityReferenceUtil } from '../../../../shared/utils/entity-reference.util';

/**
 * ViewModel for the lister component of Cartões. Responsible for loading the list of cartões
 * filtered by the banco selected in the header, and loading extrato details for each cartão.
 */
@Injectable()
export class CartoesCreditoListViewModel {
  private service = inject(CartoesCreditoService);
  private notification = inject(NotificationService);
  public auth = inject(AuthService);
  private selectedBanco = inject(SelectedBancoService);
  public formatEntityReference = formatEntityReferenceUtil;

  // State
  readonly isLoading$ = new BehaviorSubject<boolean>(false);
  readonly cartoes$ = new BehaviorSubject<CartoesCreditoModel[]>([]);

  // Map to store extrato details per cartão ID
  private extratosMap = new Map<string, ExtratoCartaoDTO>();
  // Map to cache percentage used per cartão (computed from extrato endpoint)
  private percentMap = new Map<string, number>();

  /**
   * Expose whether a banco is selected for template checks (e.g., show create button)
   */
  get hasBancoSelected(): boolean {
    return !!this.selectedBanco.currentBancoId;
  }

  constructor() {
    // Recarregar automaticamente sempre que o banco selecionado mudar
    this.selectedBanco.selectedBancoId$.subscribe(bancoId => {
      this.loadCartoes(bancoId);
    });
  }

  /**
   * Loads cartões for the optionally provided bancoId. If bancoId is undefined/null, it will
   * clear the list (or optionally load all cartões if that is desired).
   */
  loadCartoes(bancoId?: string | null): void {
    this.isLoading$.next(true);

    // If no banco selected, clear list and stop
    if (!bancoId) {
      this.cartoes$.next([]);
      this.extratosMap.clear();
      this.isLoading$.next(false);
      return;
    }

    // Load cartões filtered by bancoId
    this.service.getAll(bancoId).subscribe({
      next: (dtos) => {
        const models = CartoesCreditoMapper.toModelArray(dtos);
        this.cartoes$.next(models);

        // Load extratos for all cartões
        this.loadDetalhes(models);
      },
      error: (_err) => {
        this.notification.error('Falha ao carregar cartões');
        this.isLoading$.next(false);
      }
    });
  }

  /**
   * Load extrato details for all cartões
   */
  private loadDetalhes(cartoes: CartoesCreditoModel[]): void {
    if (cartoes.length === 0) {
      this.isLoading$.next(false);
      return;
    }

    // Reset maps for fresh load
    this.extratosMap.clear();
    this.percentMap.clear();

    // Load extratos for all cartões
    const extratoRequests = cartoes.map(cartao =>
      this.service.getExtrato(cartao.id)
    );

    forkJoin(extratoRequests).subscribe({
      next: (extratos) => {
        extratos.forEach((extrato, index) => {
          const cartao = cartoes[index];
          this.extratosMap.set(cartao.id, extrato);

          // Precompute percentage using extrato.saldoAtual when available
          const limite = cartao.limiteCredito?.valor ?? 0;
          const saldoAtualFromExtrato = extrato?.saldoAtual?.valor;
          const saldo = typeof saldoAtualFromExtrato === 'number' ? saldoAtualFromExtrato : (cartao.saldoUtilizado?.valor ?? 0);

          let percent = 0;
          if (limite && limite > 0) {
            percent = (saldo / limite) * 100;
            if (!isFinite(percent) || isNaN(percent)) percent = 0;
            if (percent < 0) percent = 0;
            if (percent > 100) percent = 100;
          }

          this.percentMap.set(cartao.id, Math.round(percent));
        });
        this.isLoading$.next(false);
      },
      error: () => {
        // If extrato loading fails, still show cartões
        this.isLoading$.next(false);
      }
    });
  }

  /**
   * Get extrato details for a specific cartão
   */
  getExtrato(cartaoId: string): ExtratoCartaoDTO | null {
    return this.extratosMap.get(cartaoId) || null;
  }

  getValorAPagar(cartaoId: string): number {
    const extrato = this.extratosMap.get(cartaoId);
    if (!extrato) return 0;
    return extrato.saldoAtual?.valor ?? 0;
  }

  /**
   * Calculate percentage of credit limit used
   */
  getPercentagemUtilizada(cartao: CartoesCreditoModel): number {
    // First prefer cached computed percentage from extrato endpoint
    const cached = this.percentMap.get(cartao.id);
    if (typeof cached === 'number') return cached;

    // Fallback to using extrato map if present
    const extrato = this.extratosMap.get(cartao.id);
    const limite = cartao.limiteCredito?.valor ?? 0;
    if (!limite || limite === 0) return 0;

    const saldoAtualFromExtrato = extrato?.saldoAtual?.valor;
    // Fallback to the cartao model's saldoUtilizado if extrato not yet loaded
    const saldo = typeof saldoAtualFromExtrato === 'number' ? saldoAtualFromExtrato : (cartao.saldoUtilizado?.valor ?? 0);

    let percent = (saldo / limite) * 100;
    if (!isFinite(percent) || isNaN(percent)) return 0;
    if (percent < 0) percent = 0;
    if (percent > 100) percent = 100;
    return Math.round(percent);
  }

  /**
   * Format date to dd/MM/yyyy
   */
  formatDate(isoDate: string | undefined | null): string {
    if (!isoDate) {
      console.warn('[CartoesCreditoListViewModel] formatDate - Missing date');
      return '-';
    }
    try {
      const date = new Date(isoDate);
      // Check if date is valid
      if (isNaN(date.getTime())) {
        console.warn('[CartoesCreditoListViewModel] formatDate - Invalid date:', isoDate);
        return '-';
      }
      const day = date.getDate().toString().padStart(2, '0');
      const month = (date.getMonth() + 1).toString().padStart(2, '0');
      const year = date.getFullYear();
      return `${day}/${month}/${year}`;
    } catch (error) {
      console.error('[CartoesCreditoListViewModel] formatDate - Error formatting date:', isoDate, error);
      return '-';
    }
  }

  /**
   * Deletes a cartão by id after confirming with the user. If the deletion is successful, it reloads the data to reflect
   * the changes.
   * @param id The id of the cartão to delete
   */
  deleteCartao(id: string): void {
    if (!id) return;

    // simple confirmation
    if (!confirm('Tem a certeza que pretende eliminar este Cartão?')) return;

    this.service.delete(id).subscribe({
      next: () => {
        this.notification.success('Cartão eliminado');
        // reload current banco selection
        this.loadCartoes(this.selectedBanco.currentBancoId);
      },
      error: (err) => {
        console.error('[FRONTEND] CartoesCreditoListViewModel.deleteCartao - Error:', err);
        this.notification.error('Falha ao eliminar cartão');
      }
    });
  }
}

import { Injectable, inject } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { Router } from '@angular/router';
import { CartoesCreditoService } from '../../services/cartoes-credito.service';
import { NotificationService } from '../../../../services/notification.service';
import { CartoesCreditoModel } from '../../models/cartoes-credito.model';
import { CartoesCreditoMapper } from '../../mappers/cartoes-credito.mapper';
import { ExtratoCartaoDTO } from '../../dto/cartoes-credito.dto';

/**
 * Simplified ViewModel for the Cartões Pagar component.
 * Only responsibilities:
 * - load card by id
 * - compute default periodo for pagar
 * - call pagar endpoint
 */
@Injectable()
export class CartoesCreditoPagarViewModel {
  private service = inject(CartoesCreditoService);
  private notification = inject(NotificationService);
  private router = inject(Router);

  // State
  readonly isLoading$ = new BehaviorSubject<boolean>(false);
  readonly cartao$ = new BehaviorSubject<CartoesCreditoModel | null>(null);
  readonly extrato$ = new BehaviorSubject<ExtratoCartaoDTO | null>(null);

  constructor() {}

  /**
   * Loads the card data by ID and updates the state accordingly.
   * @param id
   */
  loadData(id: string): void {
    if (!id) return;
    this.isLoading$.next(true);

    this.service.getById(id).subscribe({
      next: (dto) => {
        const model = CartoesCreditoMapper.toModel(dto);
        this.cartao$.next(model);

        this.service.getExtrato(id).subscribe({
          next: (extrato) => {
            this.extrato$.next(extrato);
            this.isLoading$.next(false);
          },
          error: () => {
            this.isLoading$.next(false);
          }
        });
      },
      error: (_err) => {
        this.notification.error('Falha ao carregar cartão');
        this.isLoading$.next(false);
        this.router.navigate(['/cartoes-credito']);
      }
    });
  }

  /**
   * Compute default periodo ISO strings for the pagar form based on the cartao's current periodo.fecho.
   * Default start = day after current fecho. Default end = start + 1 month - 1 day.
   * Returns { dataInicioISO, dataFimISO } where ISO is yyyy-MM-dd suitable for <input type="date">.
   */
  computeDefaultPeriodoISO(cartao: CartoesCreditoModel): { dataInicioISO: string; dataFimISO: string } | null {
    if (!cartao || !cartao.periodo || !cartao.periodo.dataFim) return null;
    const fecho = new Date(cartao.periodo.dataFim);
    if (isNaN(fecho.getTime())) return null;

    // start = day after fecho
    const start = new Date(fecho.getTime());
    start.setDate(start.getDate() + 1);

    // end = start + 1 month - 1 day
    const end = new Date(start.getTime());
    const startMonth = end.getMonth();
    end.setMonth(end.getMonth() + 1);
    // if adding month rolled over day (e.g., Jan 31 -> Mar 3), adjust by setting to last day of previous month
    if (end.getMonth() !== ((startMonth + 1) % 12)) {
      // set to last day of the target month
      end.setDate(0); // day 0 of month -> last day of previous month
    }
    // now subtract 1 day to make it end = start + 1 month - 1 day
    end.setDate(end.getDate() - 1);

    const pad = (n: number) => String(n).padStart(2, '0');
    const toISODate = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;

    return { dataInicioISO: toISODate(start), dataFimISO: toISODate(end) };
  }

  /**
   * Submits a pagar request for the cartão. The form gives periodo as ISO date strings (yyyy-MM-dd) so we need
   * to parse them into {dia, mes, ano} structures expected by the API PeriodoDTO.
   */
  submitPagar(id: string, periodoRaw: { dataInicio: string; dataFim: string }): void {
    if (!id) return;
    if (!periodoRaw || !periodoRaw.dataInicio || !periodoRaw.dataFim) {
      this.notification.error('Periodo inválido');
      return;
    }

    // parse yyyy-MM-dd or other
    const parseParts = (isoOrStr: string) => {
      const m = String(isoOrStr).trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
      if (m) return { dia: Number(m[3]), mes: Number(m[2]), ano: Number(m[1]) };
      const d = new Date(isoOrStr);
      if (isNaN(d.getTime())) return null;
      return { dia: d.getDate(), mes: d.getMonth() + 1, ano: d.getFullYear() };
    };

    const inicio = parseParts(periodoRaw.dataInicio);
    const fim = parseParts(periodoRaw.dataFim);
    if (!inicio || !fim) {
      this.notification.error('Datas inválidas. Use o selector de datas para definir o período.');
      return;
    }

    const payload: any = { novoPeriodo: { inicio, fecho: fim } };

    this.isLoading$.next(true);
    this.service.pagar(id, payload).subscribe({
      next: () => {
        this.notification.success('Cartão pago com sucesso!');
        this.isLoading$.next(false);
        this.router.navigate(['/cartoes-credito']);
      },
      error: (err) => {
        console.error('[FRONTEND] pagar erro', err);
        this.notification.error('Falha ao pagar o cartão!');
        this.isLoading$.next(false);
      }
    });
  }
}

import {Injectable} from '@angular/core';
import {HttpClient, HttpParams} from '@angular/common/http';
import {Observable} from 'rxjs';
import {environment} from '../../../../environments/environment';
import {
  CartoesCreditoDTO,
  CartoesCreditoInputDTO,
  CartoesCreditoUpdateDTO,
  ExtratoCartaoDTO,
  PeriodoDTO
} from '../dto/cartoes-credito.dto';
import {TransacoesDTO} from '../../transacoes/dto/transacoes.dto';

@Injectable({providedIn: 'root'})
export class CartoesCreditoService {
  private apiUrl = `${environment.apiBaseUrl}/cartao`;

  constructor(private http: HttpClient) {
  }

  getAll(bancoId?: string): Observable<CartoesCreditoDTO[]> {
    const options: { params?: HttpParams; withCredentials?: boolean } = { withCredentials: true };
    if (bancoId) {
      options.params = new HttpParams().set('bancoId', bancoId);
    }

    return this.http.get<CartoesCreditoDTO[]>(this.apiUrl, options);
  }

  getById(id: string): Observable<CartoesCreditoDTO> {
    return this.http.get<CartoesCreditoDTO>(`${this.apiUrl}/${id}`, {withCredentials: true});
  }

  create(dto: CartoesCreditoInputDTO): Observable<CartoesCreditoDTO> {
    return this.http.post<CartoesCreditoDTO>(this.apiUrl, dto, {withCredentials: true});
  }

  update(id: string, dto: CartoesCreditoUpdateDTO): Observable<CartoesCreditoDTO> {
    return this.http.patch<CartoesCreditoDTO>(`${this.apiUrl}/${id}`, dto, {withCredentials: true});
  }

  delete(id: string): Observable<any> {
    return this.http.delete(`${this.apiUrl}/${id}`, {withCredentials: true});
  }

  getExtrato(id: string): Observable<ExtratoCartaoDTO> {
    return this.http.get<ExtratoCartaoDTO>(`${this.apiUrl}/${id}/extrato`, {withCredentials: true});
  }

  pagar(id: string, dto: PeriodoDTO): Observable<TransacoesDTO> {
    return this.http.post<TransacoesDTO>(`${this.apiUrl}/${id}/pagar`, dto, {withCredentials: true});
  }
}

