/**
 * ViewModel for the despesas recorrentes list component.
 */
@Injectable()
export class DespesasRecorrentesListarRegrasViewModel {
  private service = inject(DespesasRecorrentesService);
  private notification = inject(NotificationService);
  private selectedBanco = inject(SelectedBancoService);

  // State
  readonly isLoading$ = new BehaviorSubject<boolean>(false);
  readonly regras$ = new BehaviorSubject<DespesaRecorrenteModel[]>([]);

  constructor() {
    // Reload when selected bank changes
    this.selectedBanco.selectedBancoId$.subscribe(() => this.loadData());
  }

  get bancoId(): string | null {
    return this.selectedBanco.currentBancoId;
  }

  formatAgendamento(regra: DespesaRecorrenteModel): string {
    switch (regra.tipo) {
      case 'Despesa Semanal':
        return this.formatSemanal(regra.diaDaSemana);
      case 'Despesa Mensal':
        return regra.diaDoMes != null ? `Todo dia ${regra.diaDoMes}` : 'Sem dia definido';
      case 'Despesa Anual':
        return regra.diaDoMes != null && regra.mes != null
          ? `Todo dia ${regra.diaDoMes} de ${this.getMesLabel(regra.mes)}`
          : 'Sem dia definido';
      case 'Poupança':
        return regra.diaDoMes != null ? `Todo dia ${regra.diaDoMes}` : 'Sem dia definido';
      default:
        return 'Sem dia definido';
    }
  }

  getTipoClass(tipo: TipoDespesaRecorrente | string): string {
    switch (tipo) {
      case 'Despesa Semanal':
        return 'badge--semanal';
      case 'Despesa Mensal':
        return 'badge--mensal';
      case 'Despesa Anual':
        return 'badge--anual';
      case 'Poupança':
        return 'badge--poupanca';
      default:
        return '';
    }
  }

  /**
   * Loads the list of despesas recorrentes regras. This method is called when the component initializes and can be
   * called again to refresh the data.
   */
  loadData(): void {
    this.isLoading$.next(true);
    const bancoId = this.bancoId ?? undefined;
    this.service.getAll(bancoId).subscribe({
      next: (dtos) => {
        this.regras$.next(DespesasRecorrentesMapper.toModelArray(dtos));
        this.isLoading$.next(false);
      },
      error: () => {
        this.notification.error('Falha ao carregar regras');
        this.isLoading$.next(false);
      }
    });
  }

  /**
   * Deletes uma despesa recorrente regra by id after confirming with the user. If the deletion is successful, it reloads the data to reflect
   * the changes.
   * @param id The id of the despesa recorrente regra to delete
   */
  deleteRegra(id: string): void {
    if (!id) return;
    if (!confirm('Tem a certeza que pretende eliminar esta regra?')) return;

    this.service.delete(id).subscribe({
      next: () => {
        this.notification.success('Regra eliminada');
        this.loadData();
      },
      error: () => this.notification.error('Falha ao eliminar regra')
    });
  }

  private formatSemanal(diaDaSemana?: number): string {
    if (diaDaSemana == null) return 'Sem dia definido';

    const labels: Record<number, string> = {
      1: 'segundas-feiras',
      2: 'terças-feiras',
      3: 'quartas-feiras',
      4: 'quintas-feiras',
      5: 'sextas-feiras',
      6: 'sábados',
      7: 'domingos'
    };

    const label = labels[diaDaSemana];
    if (!label) return 'Sem dia definido';

    return diaDaSemana >= 6 ? `Todos os ${label}` : `Todas as ${label}`;
  }

  private getMesLabel(mes: number): string {
    const labels: Record<number, string> = {
      1: 'janeiro',
      2: 'fevereiro',
      3: 'março',
      4: 'abril',
      5: 'maio',
      6: 'junho',
      7: 'julho',
      8: 'agosto',
      9: 'setembro',
      10: 'outubro',
      11: 'novembro',
      12: 'dezembro'
    };

    return labels[mes] ?? String(mes);
  }
}

import { Injectable, inject } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { CategoriasService } from '../../../categorias/services/categorias.service';
import { NotificationService } from '../../../../services/notification.service';
import { SelectedBancoService } from '../../../../services/selected-banco.service';
import { TransacoesService } from '../../../transacoes/services/transacoes.service';
import { TransacoesMapper } from '../../../transacoes/mappers/transacoes.mapper';
import { TransacaoModel } from '../../../transacoes/models/transacoes.model';
import { CategoriasDTO } from '../../../categorias/dto/categorias.dto';
import { DespesasRecorrentesService } from '../../services/despesas-recorrentes.service';
import { DespesasRecorrentesMapper } from '../../mappers/despesas-recorrentes.mapper';
import { DespesaRecorrenteModel } from '../../models/despesas-recorrentes.model';
import { DespesaFilters, filterByPeriod } from './despesas-recorrentes-listar.filter';

export type { PeriodFilter, DespesaFilters } from './despesas-recorrentes-listar.filter';

@Injectable()
export class DespesasRecorrentesListViewModel {
  private transacoesService = inject(TransacoesService);
  private despesasRecorrentesService = inject(DespesasRecorrentesService);
  private categoriasService = inject(CategoriasService);
  private notification = inject(NotificationService);
  private selectedBanco = inject(SelectedBancoService);

  readonly isLoading$ = new BehaviorSubject<boolean>(false);

  /** Left column — Pendente */
  readonly pendentes$ = new BehaviorSubject<TransacaoModel[]>([]);
  /** Right column — Concluído */
  readonly concluidas$ = new BehaviorSubject<TransacaoModel[]>([]);
  /** Recurring expense rules without valor/diaDoMes configured */
  readonly despesasSemValorSemanal$ = new BehaviorSubject<DespesaRecorrenteModel[]>([]);
  readonly despesasSemValorMensal$ = new BehaviorSubject<DespesaRecorrenteModel[]>([]);
  readonly despesasSemValorAnual$ = new BehaviorSubject<DespesaRecorrenteModel[]>([]);
  readonly despesasSemValorPoupanca$ = new BehaviorSubject<DespesaRecorrenteModel[]>([]);

  readonly categorias$ = new BehaviorSubject<CategoriasDTO[]>([]);

  pendenteFilters: DespesaFilters = { categoriaId: '', period: '' };
  concluidaFilters: DespesaFilters = { categoriaId: '', period: 'Este Mês' };

  /** Set of transaction ids currently being processed to prevent duplicate clicks */
  private busyIds = new Set<string>();

  readonly PERIODS = ['Este Mês', 'Últimos 3 Meses', 'Último Ano'] as const;

  constructor() {
    this.selectedBanco.selectedBancoId$.subscribe(() => this.loadAll());
  }

  get bancoId(): string | null {
    return this.selectedBanco.currentBancoId;
  }

  /** Load categories then refresh both columns and sem-valor list */
  loadAll(): void {
    this.isLoading$.next(true);
    this.categoriasService.getAll().subscribe({
      next: cats => {
        this.categorias$.next(cats);
        this.loadPendentes();
        this.loadConcluidas();
        this.loadDespesasSemValor();
      },
      error: err => {
        console.error('[DespesasRecorrentesListViewModel] loadAll error', err);
        this.notification.error('Falha ao carregar dados');
        this.isLoading$.next(false);
      }
    });
  }

  // ── Sem Valor ─────────────────────────────────────────────

  loadDespesasSemValor(): void {
    const bancoId = this.bancoId;
    if (!bancoId) {
      this.despesasSemValorSemanal$.next([]);
      this.despesasSemValorMensal$.next([]);
      this.despesasSemValorAnual$.next([]);
      this.despesasSemValorPoupanca$.next([]);
      return;
    }
    this.despesasRecorrentesService.getSemValorPorTipo(bancoId, 'Despesa Semanal').subscribe({
      next: dtos => this.despesasSemValorSemanal$.next(DespesasRecorrentesMapper.toModelArray(dtos)),
      error: err => { console.error('[DespesasRecorrentesListViewModel] loadDespesasSemValor error', err); }
    });
    this.despesasRecorrentesService.getSemValorPorTipo(bancoId, 'Despesa Mensal').subscribe({
      next: dtos => this.despesasSemValorMensal$.next(DespesasRecorrentesMapper.toModelArray(dtos)),
      error: err => { console.error('[DespesasRecorrentesListViewModel] loadDespesasSemValor error', err); }
    });
    this.despesasRecorrentesService.getSemValorPorTipo(bancoId, 'Despesa Anual').subscribe({
      next: dtos => this.despesasSemValorAnual$.next(DespesasRecorrentesMapper.toModelArray(dtos)),
      error: err => { console.error('[DespesasRecorrentesListViewModel] loadDespesasSemValor error', err); }
    });
    this.despesasRecorrentesService.getSemValorPorTipo(bancoId, 'Poupança').subscribe({
      next: dtos => this.despesasSemValorPoupanca$.next(DespesasRecorrentesMapper.toModelArray(dtos)),
      error: err => { console.error('[DespesasRecorrentesListViewModel] loadDespesasSemValor error', err); }
    });
  }

  // ── Pendentes column ──────────────────────────────────────

  loadPendentes(): void {
    const f = this.pendenteFilters;
    const bancoId = this.bancoId ?? undefined;

    // Categoria filter
    if (f.categoriaId) {
      this.transacoesService.getDespesaRecorrenteByCategoria(f.categoriaId, bancoId).subscribe({
        next: dtos => {
          this.pendentes$.next(TransacoesMapper.toModelArray(dtos).filter(t => t.status === 'Pendente'));
          this.isLoading$.next(false);
        },
        error: () => { this.notification.error('Falha ao filtrar despesas pendentes'); this.isLoading$.next(false); }
      });
      return;
    }

    // No filter — load by status directly
    this.transacoesService.getDespesaRecorrenteByStatus('Pendente', bancoId).subscribe({
      next: dtos => { this.pendentes$.next(TransacoesMapper.toModelArray(dtos)); this.isLoading$.next(false); },
      error: () => { this.notification.error('Falha ao carregar despesas pendentes'); this.isLoading$.next(false); }
    });
  }

  applyPendenteFilters(filters: DespesaFilters): void {
    this.pendenteFilters = { ...filters };
    this.loadPendentes();
  }

  clearPendenteFilters(): void {
    this.pendenteFilters = { categoriaId: '', period: '' };
    this.loadPendentes();
  }

  // ── Concluídas column ─────────────────────────────────────

  loadConcluidas(): void {
    const f = this.concluidaFilters;
    const bancoId = this.bancoId ?? undefined;

    // Period filter
    if (f.period && !f.categoriaId) {
      this.transacoesService.getDespesaRecorrenteByPeriod(f.period, bancoId).subscribe({
        next: dtos => {
          this.concluidas$.next(TransacoesMapper.toModelArray(dtos).filter(t => t.status === 'Concluído'));
          this.isLoading$.next(false);
        },
        error: () => { this.notification.error('Falha ao filtrar despesas concluídas'); this.isLoading$.next(false); }
      });
      return;
    }

    // Categoria filter (or both)
    if (f.categoriaId) {
      this.transacoesService.getDespesaRecorrenteByCategoria(f.categoriaId, bancoId).subscribe({
        next: dtos => {
          let all = TransacoesMapper.toModelArray(dtos).filter(t => t.status === 'Concluído');
          if (f.period) all = filterByPeriod(all, f.period);
          this.concluidas$.next(all);
          this.isLoading$.next(false);
        },
        error: () => { this.notification.error('Falha ao filtrar despesas concluídas'); this.isLoading$.next(false); }
      });
      return;
    }

    // No filter — load by status directly
    this.transacoesService.getDespesaRecorrenteByStatus('Concluído', bancoId).subscribe({
      next: dtos => { this.concluidas$.next(TransacoesMapper.toModelArray(dtos)); this.isLoading$.next(false); },
      error: () => { this.notification.error('Falha ao carregar despesas concluídas'); this.isLoading$.next(false); }
    });
  }

  applyConcluidaFilters(filters: DespesaFilters): void {
    this.concluidaFilters = { ...filters };
    this.loadConcluidas();
  }

  clearConcluidaFilters(): void {
    this.concluidaFilters = { categoriaId: '', period: 'Este Mês' };
    this.loadConcluidas();
  }

  // ── Helpers ───────────────────────────────────────────────

  /**
   * Returns true if the transaction id is currently being processed
   */
  isBusy(id: string): boolean {
    return this.busyIds.has(id);
  }

  /**
   * Conclude a recurring transaction: calls the correct endpoint depending on the transaction type.
   * Supports 'Despesa Mensal' and 'Poupança'. Refreshes lists on success.
   */
  concluirTransacao(t: TransacaoModel): void {
    if (!t || !t.id) return;
    if (this.isBusy(t.id)) return;

    // Only allow concluding pending items
    if (t.status !== 'Pendente') {
      this.notification.info('Transaction is not pending');
      return;
    }

    let obs$;
    if (t.tipo === 'Despesa Mensal' || 'Despesa Semanal' || 'Despesa Anual') {
      obs$ = this.transacoesService.concluirDespesaRecorrente(t.id);
    } else if (t.tipo === 'Poupança' || t.tipo === 'Poupanca') {
      obs$ = this.transacoesService.concluirPoupanca(t.id);
    } else {
      this.notification.info('Não é possível concluir este tipo de transação');
      return;
    }

    this.busyIds.add(t.id);
    this.isLoading$.next(true);

    obs$.subscribe({
      next: () => {
        this.notification.success('Transação concluída com sucesso');
        // reload both columns to reflect new status
        this.loadPendentes();
        this.loadConcluidas();
        this.busyIds.delete(t.id);
        this.isLoading$.next(false);
      },
      error: (err) => {
        console.error('concluirTransacao error', err);
        this.notification.error('Falha ao concluir transação');
        this.busyIds.delete(t.id);
        this.isLoading$.next(false);
      }
    });
  }

  /**
   * Delete a transaction by its domain id.
   * Calls API, removes the transaction from the current lists and notifies the user.
   */
  public deleteTransacao(transacaoId: string): void {
    if (!transacaoId) return;
    if (this.isBusy(transacaoId)) return;

    this.busyIds.add(transacaoId);
    this.isLoading$.next(true);

    this.transacoesService.delete(transacaoId).subscribe({
      next: () => {
        // Remove from pendentes and concluidas lists if present
        this.pendentes$.next(this.pendentes$.getValue().filter(t => t.id !== transacaoId));
        this.concluidas$.next(this.concluidas$.getValue().filter(t => t.id !== transacaoId));

        this.notification.success('Transação eliminada com sucesso');
        this.busyIds.delete(transacaoId);
        this.isLoading$.next(false);
      },
      error: (err) => {
        console.error('[DespesasRecorrentesListViewModel] deleteTransacao error', err);
        this.notification.error('Falha ao eliminar transação');
        this.busyIds.delete(transacaoId);
        this.isLoading$.next(false);
      }
    });
  }
}

import { Injectable, inject } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { Router } from '@angular/router';
import { DespesasRecorrentesService } from '../../services/despesas-recorrentes.service';
import { NotificationService } from '../../../../services/notification.service';
import { SelectedBancoService } from '../../../../services/selected-banco.service';
import { ContasService } from '../../../contas/services/contas.service';
import { CategoriasService } from '../../../categorias/services/categorias.service';
import { ContasDto } from '../../../contas/dto/contas.dto';
import { CategoriasDTO } from '../../../categorias/dto/categorias.dto';
import { CreateDespesaRecorrenteDTO } from '../../dto/despesas-recorrentes.dto';

@Injectable()
export class DespesasRecorrentesNovaRegraViewModel {
  private service = inject(DespesasRecorrentesService);
  private notification = inject(NotificationService);
  private router = inject(Router);
  private selectedBanco = inject(SelectedBancoService);
  private contasService = inject(ContasService);
  private categoriasService = inject(CategoriasService);

  readonly isLoading$ = new BehaviorSubject<boolean>(false);
  readonly contas$ = new BehaviorSubject<ContasDto[]>([]);
  readonly categorias$ = new BehaviorSubject<CategoriasDTO[]>([]);

  get selectedBancoId(): string | null {
    return this.selectedBanco.currentBancoId;
  }

  constructor() {
    this.selectedBanco.selectedBancoId$.subscribe(id => {
      this.loadContas(id);
    });
    this.loadCategorias();
  }

  private loadContas(bancoId: string | null): void {
    this.contasService.getAll(bancoId ?? undefined).subscribe({
      next: contas => this.contas$.next(contas),
      error: () => this.notification.error('Falha ao carregar contas')
    });
  }

  private loadCategorias(): void {
    this.categoriasService.getAll().subscribe({
      next: cats => this.categorias$.next(cats),
      error: () => this.notification.error('Falha ao carregar categorias')
    });
  }

  submit(formData: CreateDespesaRecorrenteDTO): void {
    if (!this.selectedBancoId) {
      this.notification.error('Selecione um banco antes de criar a regra');
      return;
    }
    this.isLoading$.next(true);
    this.service.create(formData).subscribe({
      next: () => {
        this.notification.success('Regra criada com sucesso');
        this.isLoading$.next(false);
        this.router.navigate(['/despesas-recorrentes']);
      },
      error: () => {
        this.notification.error('Falha ao criar regra');
        this.isLoading$.next(false);
      }
    });
  }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { DespesaRecorrenteDTO, CreateDespesaRecorrenteDTO, UpdateDespesaRecorrenteDTO, GerarTransacaoSemValorDTO } from '../dto/despesas-recorrentes.dto';

@Injectable({ providedIn: 'root' })
export class DespesasRecorrentesService {
  private baseUrl = `${environment.apiBaseUrl}/despesa-recorrente`;

  constructor(private http: HttpClient) {}

  /** Get all recurring expense rules for the authenticated user, optionally filtered by bank */
  getAll(bancoId?: string): Observable<DespesaRecorrenteDTO[]> {
    if (bancoId) {
      const params = new HttpParams().set('bancoId', bancoId);
      return this.http.get<DespesaRecorrenteDTO[]>(this.baseUrl, { params, withCredentials: true });
    }
    return this.http.get<DespesaRecorrenteDTO[]>(this.baseUrl, { withCredentials: true });
  }

  /** Get a recurring expense rule by id */
  getById(id: string): Observable<DespesaRecorrenteDTO> {
    return this.http.get<DespesaRecorrenteDTO>(`${this.baseUrl}/${id}`, { withCredentials: true });
  }

  /** Create a new recurring expense rule */
  create(dto: CreateDespesaRecorrenteDTO): Observable<DespesaRecorrenteDTO> {
    return this.http.post<DespesaRecorrenteDTO>(this.baseUrl, dto, { withCredentials: true });
  }

  /** Update a recurring expense rule */
  update(id: string, dto: UpdateDespesaRecorrenteDTO): Observable<DespesaRecorrenteDTO> {
    return this.http.patch<DespesaRecorrenteDTO>(`${this.baseUrl}/${id}`, dto, { withCredentials: true });
  }

  /** Delete a recurring expense rule */
  delete(id: string): Observable<void> {
    return this.http.delete<void>(`${this.baseUrl}/${id}`, { withCredentials: true });
  }

  /**
   * Get recurring expenses that have both valor and diaDoMes configured, optionally filtered by bank
   * Matches backend route: GET /despesa-recorrente/com-valor?bancoId=...
   */
  getComValor(bancoId?: string): Observable<DespesaRecorrenteDTO[]> {
    let params = new HttpParams();
    if (bancoId) params = params.set('bancoId', bancoId);
    return this.http.get<DespesaRecorrenteDTO[]>(`${this.baseUrl}/com-valor`, { params, withCredentials: true });
  }

  /**
   * Get recurring expenses that have no valor/diaDoMes configured (icon/nome only), optionally filtered by bank and/or tipo
   * Matches backend route: GET /despesa-recorrente/sem-valor?bancoId=...&tipo=...
   */
  getSemValor(bancoId?: string, tipo?: string): Observable<DespesaRecorrenteDTO[]> {
    let params = new HttpParams();
    if (bancoId) params = params.set('bancoId', bancoId);
    if (tipo) params = params.set('tipo', tipo);
    return this.http.get<DespesaRecorrenteDTO[]>(`${this.baseUrl}/sem-valor`, { params, withCredentials: true });
  }

  /**
   * Get recurring expenses without valor filtered by tipo
   * Matches backend route: GET /despesa-recorrente/sem-valor?bancoId=...&tipo=...
   */
  getSemValorPorTipo(bancoId: string, tipo: string): Observable<DespesaRecorrenteDTO[]> {
    return this.getSemValor(bancoId, tipo);
  }

  /**
   * Manually generate a pending transaction for a sem-valor recurring expense.
   * Matches backend route: POST /despesa-recorrente/:id/gerar-transacao
   */
  gerarTransacao(id: string, dto: GerarTransacaoSemValorDTO): Observable<unknown> {
    return this.http.post(`${this.baseUrl}/${id}/gerar-transacao`, dto, { withCredentials: true });
  }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { EstatisticasDto } from '../dto/estatisticas.dto';

@Injectable({ providedIn: 'root' })
export class EstatisticasService {
  private apiUrl = `${environment.apiBaseUrl}/estatisticas`;

  constructor(private http: HttpClient) {}

  /**
   * Fetch statistics for a given banco.
   * If month/year are omitted, the backend will use the current month (and the "rolling month" behavior when appropriate).
   */
  getEstatisticas(bancoId: string, month?: number, year?: number): Observable<EstatisticasDto> {
    let params = new HttpParams().set('bancoId', bancoId);
    if (month !== undefined) params = params.set('month', String(month));
    if (year !== undefined) params = params.set('year', String(year));
    return this.http.get<EstatisticasDto>(this.apiUrl, { params, withCredentials: true });
  }
}

import { Injectable, inject } from '@angular/core';
import { BehaviorSubject, map, catchError, of, switchMap, combineLatest, debounceTime, tap } from 'rxjs';
import { BancosService } from '../../bancos/services/bancos.service';
import { BancosMapper } from '../../bancos/mappers/bancos.mapper';
import { NotificationService } from '../../../services/notification.service';
import { SelectedBancoService } from '../../../services/selected-banco.service';
import { EstatisticasService } from '../services/estatisticas.service';
import { EstatisticasModel } from '../models/estatisticas.model';
import { EstatisticasMapper } from '../mappers/estatisticas.mapper';
import { BancosModel } from '../../bancos/models/bancos.model';

@Injectable()
export class EstatisticasViewModel {
  private estatisticasService = inject(EstatisticasService);
  private bancosService = inject(BancosService);
  private notification = inject(NotificationService);
  private selectedBancoService = inject(SelectedBancoService);

  readonly estatisticas$ = new BehaviorSubject<EstatisticasModel | null>(null);
  readonly isLoading$ = new BehaviorSubject<boolean>(false);
  readonly bancos$ = new BehaviorSubject<BancosModel[]>([]);

  readonly selectedMonth$ = new BehaviorSubject<number | null>(null);
  readonly selectedYear$ = new BehaviorSubject<number | null>(null);

  readonly hasBancoSelected$ = this.selectedBancoService.selectedBancoId$.pipe(
    map(id => !!id)
  );

  private selectedBancoId: string | null = null;

  constructor() {
    combineLatest([
      this.selectedBancoService.selectedBancoId$,
      this.selectedMonth$,
      this.selectedYear$
    ]).pipe(
      debounceTime(100)
    ).subscribe(([bancoId, month, year]) => {
      this.loadEstatisticas(bancoId, month, year);
    });
  }

  loadBancos(): void {
    this.bancosService.getAll().subscribe({
      next: (dtos) => {
        const models = BancosMapper.toModelArray(dtos);
        this.bancos$.next(models);

        const storedId = this.selectedBancoService.currentBancoId;
        if (storedId && !models.some(b => b.id === storedId)) {
          this.selectedBancoService.clearSelection();
        }
      },
      error: (err: any) => {
        if (err?.status !== 401) {
          console.error('[FRONTEND] EstatisticasViewModel.loadBancos -', err);
          this.notification.error('Falha ao carregar bancos');
        }
        this.bancos$.next([]);
      }
    });
  }

  setMonthYear(month: number | null, year: number | null): void {
    this.selectedMonth$.next(month);
    this.selectedYear$.next(year);
  }

  private loadEstatisticas(bancoId: string | null, month: number | null, year: number | null): void {
    if (!bancoId) {
      this.estatisticas$.next(null);
      return;
    }

    this.isLoading$.next(true);
    this.estatisticasService.getEstatisticas(bancoId, month ?? undefined, year ?? undefined).subscribe({
      next: (dto) => {
        const model = EstatisticasMapper.toModel(dto);
        this.estatisticas$.next(model);
        this.isLoading$.next(false);
      },
      error: (err) => {
        console.error('[FRONTEND] EstatisticasViewModel.loadEstatisticas -', err);
        this.notification.error('Falha ao carregar estatísticas');
        this.isLoading$.next(false);
      }
    });
  }
}

