import {Injectable, signal, computed} from '@angular/core';
import {Role} from '../features/auth/services/auth.service';

/**
 * Menu item definition.
 */
export interface MenuItem {
  id: string;
  labelKey: string;
  icon: string;
  route?: string;
  roles: Role[];
  children?: MenuItem[];
}

/**
 * Service providing the application menu structure and filtering by user role.
 */
@Injectable({
  providedIn: 'root'
})
export class MenuService {

  private all = signal<MenuItem[]>([
    // Home
    {
      id: 'Dashboard',
      labelKey: 'Dashboard',
      icon: '/icons/dashboard.svg',
      route: '/dashboard',
      roles: ['Admin', 'User']
    },

    {
      id: 'Estatísticas',
      labelKey: 'Estatísticas',
      icon: '/icons/estatisticas.svg',
      route: '/estatisticas',
      roles: ['Admin', 'User']
    },

    {
      id: 'Bancos',
      labelKey: 'Bancos',
      icon: '/icons/bancos.svg',
      route: '/bancos',
      roles: ['Admin', 'User']
    },

    {
      id: 'Contas',
      labelKey: 'Contas',
      icon: '/icons/contas.svg',
      route: '/contas',
      roles: ['Admin', 'User']
    },

    {
      id: 'Cartões de Crédito',
      labelKey: 'Cartões de Crédito',
      icon: '/icons/cartoes.svg',
      route: '/cartoes-credito',
      roles: ['Admin', 'User']
    },

    {
      id: 'Transações',
      labelKey: 'Transações',
      icon: '/icons/transacoes.svg',
      route: '/transacoes',
      roles: ['Admin', 'User']
    },

    {
      id: 'Despesas Recorrentes',
      labelKey: 'Despesas Recorrentes',
      icon: '/icons/despesas_mensais.svg',
      route: '/despesas-recorrentes',
      roles: ['Admin', 'User']
    },

    {
      id: 'Categorias',
      labelKey: 'Categorias',
      icon: '/icons/categorias.svg',
      route: '/categorias',
      roles: ['Admin']
    },

    {
      id: 'Utilizadores',
      labelKey: 'Utilizadores',
      icon: '/icons/usuarios.svg',
      route: '/utilizadores',
      roles: ['Admin']
    }
  ]);


  /**
   * Returns a computed menu filtered for `role`.
   * Accepts either a Role value or a function (signal/computed) returning a Role;
   * when a function is passed the returned computed will update reactively.
   */
  filteredForRole(role: Role | (() => Role)) {
    return computed(() => {
      const r: Role = typeof role === 'function' ? (role as () => Role)() : role;

      // recursive filter to support arbitrary submenu depth
      const filterItem = (item: MenuItem): MenuItem | undefined => {
        // if item has children, filter them recursively
        const children = item.children?.map(filterItem).filter((c): c is MenuItem => !!c) ?? [];

        // include item if its roles include r or any child remains
        if (item.roles.includes(r) || children.length > 0) {
          // return a shallow copy, only include children when present
          return children.length > 0 ? {...item, children} : {...item, children: undefined};
        }

        return undefined;
      };

      // filter items and their children by role
      return this.all().map(filterItem).filter((it): it is MenuItem => !!it);
    });
  }
}

import { Injectable, signal } from '@angular/core';

export type Notification = {
  id: string;
  type: 'success' | 'error' | 'info' | 'warning';
  message: string;
  timeout?: number; // ms
};

@Injectable({ providedIn: 'root' })
export class NotificationService {
  // public signal list of notifications
  notifications = signal<Notification[]>([]);

  private makeId() {
    return Math.random().toString(36).slice(2, 9);
  }

  show(message: string, type: Notification['type'] = 'info', timeout = 5000) {
    const id = this.makeId();
    const n: Notification = { id, type, message, timeout };
    this.notifications.set([...(this.notifications() || []), n]);
    if (timeout && timeout > 0) {
      setTimeout(() => this.dismiss(id), timeout);
    }
    return id;
  }

  success(message: string, timeout = 4000) {
    return this.show(message, 'success', timeout);
  }

  error(message: string, timeout = 7000) {
    return this.show(message, 'error', timeout);
  }

  info(message: string, timeout = 4000) {
    return this.show(message, 'info', timeout);
  }

  warning(message: string, timeout = 5000) {
    return this.show(message, 'warning', timeout);
  }

  dismiss(id: string) {
    this.notifications.set((this.notifications() || []).filter(n => n.id !== id));
  }

  clear() {
    this.notifications.set([]);
  }
}

import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { PerfilDTO, AtualizarPerfilDTO } from '../dto/perfil.dto';
import { AuthService } from '../../auth/services/auth.service';
import { environment } from '../../../../environments/environment';

@Injectable({ providedIn: 'root' })
export class PerfilService {
  private http = inject(HttpClient);
  private auth = inject(AuthService);
  private authBase = `${environment.apiBaseUrl}/auth`;

  // GET /api/auth/:id — returns the full user with email
  getCurrent(): Observable<PerfilDTO> {
    const id = this.auth.user()?.id ?? '';
    return this.http.get<PerfilDTO>(
      `${this.authBase}/${encodeURIComponent(id)}`,
      { withCredentials: true }
    );
  }

  // PATCH /api/auth/:email — update name and/or password
  update(email: string, payload: AtualizarPerfilDTO): Observable<PerfilDTO> {
    return this.http.patch<PerfilDTO>(
      `${this.authBase}/${encodeURIComponent(email)}`,
      payload,
      { withCredentials: true }
    );
  }
}

import { Injectable, inject } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { Location } from '@angular/common';
import { PerfilService } from '../services/perfil.service';
import { NotificationService } from '../../../services/notification.service';
import { AuthService } from '../../auth/services/auth.service';
import { PerfilModel } from '../models/perfil.model';
import { PerfilMapper } from '../mappers/perfil.mapper';
import { AtualizarPerfilDTO } from '../dto/perfil.dto';

/**
 * ViewModel for the user profile component.
 */
@Injectable()
export class PerfilViewModel {
  private service = inject(PerfilService);
  private notification = inject(NotificationService);
  private auth = inject(AuthService);
  private location = inject(Location);

  readonly isLoading$ = new BehaviorSubject<boolean>(false);
  readonly isSaving$  = new BehaviorSubject<boolean>(false);
  readonly perfil$    = new BehaviorSubject<PerfilModel | null>(null);

  loadData(): void {
    this.isLoading$.next(true);
    this.service.getCurrent().subscribe({
      next: dto => {
        this.perfil$.next(PerfilMapper.toModel(dto));
        this.isLoading$.next(false);
      },
      error: () => {
        this.notification.error('Erro ao carregar perfil');
        this.isLoading$.next(false);
      }
    });
  }

  save(payload: AtualizarPerfilDTO): void {
    const email = this.perfil$.value?.email;
    if (!email) return;

    // Only send fields that were actually filled in
    const dto: AtualizarPerfilDTO = {};
    if (payload.name?.trim())     dto.name     = payload.name.trim();
    if (payload.password?.trim()) dto.password = payload.password.trim();
    if (!dto.name && !dto.password) {
      this.notification.error('Por favor altere pelo menos um campo');
      return;
    }

    this.isSaving$.next(true);
    this.service.update(email, dto).subscribe({
      next: updated => {
        this.perfil$.next(PerfilMapper.toModel(updated));
        if (dto.name) {
          const u = this.auth.user();
          if (u) this.auth.user.set({ ...u, name: dto.name });
        }
        this.notification.success('Perfil atualizado com sucesso');
        this.isSaving$.next(false);
        this.location.back();
      },
      error: err => {
        const msg = err?.error?.error ?? 'Erro ao atualizar perfil';
        this.notification.error(msg);
        this.isSaving$.next(false);
      }
    });
  }
}

import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

/**
 * Service to manage the globally selected bank across the application.
 * The selection is persisted in localStorage keyed by userId so each user
 * keeps their own banco selection across login/logout cycles.
 */
@Injectable({
  providedIn: 'root'
})
export class SelectedBancoService {
  private readonly STORAGE_PREFIX = 'selectedBancoId';
  private userId: string | null = null;
  private selectedBancoIdSubject = new BehaviorSubject<string | null>(this.loadFromStorage(null));

  /**
   * Observable that emits the currently selected banco ID.
   * Null means no banco is selected.
   */
  public selectedBancoId$: Observable<string | null> = this.selectedBancoIdSubject.asObservable();

  /**
   * Get the current selected banco ID synchronously.
   */
  get currentBancoId(): string | null {
    return this.selectedBancoIdSubject.value;
  }

  /**
   * Called after login so the service loads the banco saved for this specific user.
   */
  initForUser(userId: string): void {
    this.userId = userId;
    const saved = this.loadFromStorage(userId);
    this.selectedBancoIdSubject.next(saved);
  }

  /**
   * Set the selected banco ID and persist to localStorage.
   * @param bancoId - The banco ID to select, or null to clear selection
   */
  selectBanco(bancoId: string | null): void {
    this.selectedBancoIdSubject.next(bancoId);
    this.saveToStorage(bancoId);
  }

  /**
   * Clears the in-memory selection but does NOT remove from localStorage,
   * so the next login for the same user restores their last banco.
   */
  clearSelection(): void {
    this.userId = null;
    this.selectedBancoIdSubject.next(null);
  }

  private storageKey(userId: string | null): string {
    return userId ? `${this.STORAGE_PREFIX}_${userId}` : this.STORAGE_PREFIX;
  }

  /**
   * Load the selected banco ID from localStorage on service initialization.
   */
  private loadFromStorage(userId: string | null): string | null {
    // avoid accessing localStorage in non-browser or SSR environments
    if (typeof window === 'undefined' || typeof localStorage === 'undefined') {
      return null;
    }

    try {
      return localStorage.getItem(this.storageKey(userId));
    } catch {
      return null;
    }
  }

  /**
   * Save the selected banco ID to localStorage.
   */
  private saveToStorage(bancoId: string | null): void {
    if (typeof window === 'undefined' || typeof localStorage === 'undefined') {
      return;
    }
    try {
      const key = this.storageKey(this.userId);
      if (bancoId) {
        localStorage.setItem(key, bancoId);
      } else {
        localStorage.removeItem(key);
      }
    } catch {
      // ignore
    }
  }
}

import { Injectable, inject } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { Router } from '@angular/router';
import { TransacoesService } from '../../services/transacoes.service';
import { TransacoesInputDTO } from '../../dto/transacoes.dto';
import { NotificationService } from '../../../../services/notification.service';
import { SelectedBancoService } from '../../../../services/selected-banco.service';
import { CategoriasService } from '../../../categorias/services/categorias.service';
import { CategoriasModel } from '../../../categorias/models/categorias.model';
import { CartoesCreditoService } from '../../../cartoes-credito/services/cartoes-credito.service';

/**
 * ViewModel for the Criar Crédito component.
 * Handles loading state, credit-cards, categories and submission of a Crédito transaction.
 */
@Injectable()
export class TransacoesCriarCreditoViewModel {
  private service = inject(TransacoesService);
  private notification = inject(NotificationService);
  private router = inject(Router);
  private selectedBanco = inject(SelectedBancoService);
  private categoriasService = inject(CategoriasService);
  private cartoesService = inject(CartoesCreditoService);

  readonly isLoading$ = new BehaviorSubject<boolean>(false);
  readonly categorias$ = new BehaviorSubject<CategoriasModel[]>([]);
  readonly cartoes$ = new BehaviorSubject<any[]>([]);

  /**
   * Expose selectedBancoId from the global service so template can check if a banco is selected
   */
  get selectedBancoId(): string | null {
    return this.selectedBanco.currentBancoId;
  }

  constructor() {
    // reload accounts/cards whenever selected banco changes
    this.selectedBanco.selectedBancoId$.subscribe(id => {
      this.loadCartoes(id);
    });
    this.loadCategorias();
  }

  /**
   * Submits a new Entrada transaction.
   * Expects formData with: { data: string (ISO date), descricao, valor: { valor, moeda }, categoriaId, contaId }
   */
  submit(formData: any): void {
    this.isLoading$.next(true);

    const rawDate: string = formData.data ?? '';
    const isoMatch = rawDate.match(/^\s*(\d{4})-(\d{2})-(\d{2})\s*$/);
    let dateParts: { dia: number; mes: number; ano: number } | null = null;

    if (isoMatch) {
      dateParts = { ano: +isoMatch[1], mes: +isoMatch[2], dia: +isoMatch[3] };
    } else {
      const d = new Date(rawDate);
      if (!isNaN(d.getTime())) {
        dateParts = { dia: d.getDate(), mes: d.getMonth() + 1, ano: d.getFullYear() };
      }
    }

    if (!dateParts) {
      this.isLoading$.next(false);
      this.notification.error('Data inválida. Use o selector de data.');
      return;
    }

    const payload: TransacoesInputDTO = {
      data: dateParts,
      descricao: formData.descricao,
      valor: { valor: +formData.valor.valor, moeda: formData.valor.moeda },
      categoriaId: formData.categoriaId,
      cartaoCreditoId: formData.cartaoCreditoId || undefined,
    } as any;

    this.service.createCredito(payload).subscribe({
      next: () => {
        this.notification.success('Crédito criado com sucesso');
        this.isLoading$.next(false);
        this.router.navigate(['/transacoes']);
      },
      error: () => {
        this.notification.error('Falha ao criar crédito');
        this.isLoading$.next(false);
      }
    });
  }

  private loadCartoes(bancoId: string | null): void {
    if (!bancoId) { this.cartoes$.next([]); return; }
    this.cartoesService.getAll(bancoId).subscribe({
      next: (dtos) => this.cartoes$.next(dtos as any[]),
      error: () => this.cartoes$.next([])
    });
  }

  private loadCategorias(): void {
    this.categoriasService.getAll().subscribe({
      next: (dtos) => this.categorias$.next(dtos as CategoriasModel[]),
      error: () => this.categorias$.next([])
    });
  }
}

