import { EstatisticasModel } from '../models/estatisticas.model';

/**
 * Mapper for Statistics - converts backend DTO to frontend Model
 */
export class EstatisticasMapper {
  static toModel(dto: EstatisticasDto): EstatisticasModel {
    return {
      cashflowMensal: {
        totalIn: dto.cashflowMensal.totalIn,
        totalOut: dto.cashflowMensal.totalOut,
        netBalance: dto.cashflowMensal.netBalance
      },
      categorias: dto.categorias.map(c => ({
        categoria: {
          id: c.categoria.id,
          nome: c.categoria.nome,
          icon: c.categoria.icon
        },
        total: {
          valor: c.total.valor,
          moeda: c.total.moeda
        }
      })),
      historicoDiario: dto.historicoDiario.map(h => ({
        data: {
          dia: h.data.dia,
          mes: h.data.mes,
          ano: h.data.ano
        },
        total: {
          valor: h.total.valor,
          moeda: h.total.moeda
        }
      }))
    };
  }
}

import { PerfilDTO } from '../dto/perfil.dto';
import { PerfilModel } from '../models/perfil.model';

/**
 * Mapper for Perfis - converts between API DTO and UI Model
 */
export class PerfilMapper {
  static toModel(dto: PerfilDTO): PerfilModel {
    return {
      id:    dto.id,
      nome:  dto.name,
      email: dto.email,
      role:  dto.role,
    };
  }
}

import { TransacoesDTO } from '../dto/transacoes.dto';
import { TransacaoModel } from '../models/transacoes.model';

export class TransacoesMapper {
  /**
   * Map DTO to UI model
   * @param dto - transaction DTO from API
   */
  static toModel(dto: TransacoesDTO): TransacaoModel {
    return {
      id: dto.id,
      dia: dto.data.dia,
      mes: dto.data.mes,
      ano: dto.data.ano,
      descricao: dto.descricao,
      valor: dto.valor.valor,
      moeda: dto.valor.moeda,
      tipo: dto.tipo,
      categoria: {
        id: dto.categoria.id,
        nome: dto.categoria.nome ?? '',
        icon: dto.categoria.icon ?? ''
      },
      status: dto.status,
      conta: dto.conta ? { id: dto.conta.id, nome: dto.conta.nome, icon: dto.conta.icon, descricao: dto.conta.descricao } : undefined,
      cartaoCredito: dto.cartaoCredito ? { id: dto.cartaoCredito.id, nome: dto.cartaoCredito.nome, icon: dto.cartaoCredito.icon, descricao: dto.cartaoCredito.descricao } : undefined,
      contaDestino: dto.contaDestino ? { id: dto.contaDestino.id, nome: dto.contaDestino.nome, icon: dto.contaDestino.icon, descricao: dto.contaDestino.descricao } : undefined,
      contaPoupanca: dto.contaPoupanca ? { id: dto.contaPoupanca.id, nome: dto.contaPoupanca.nome, icon: dto.contaPoupanca.icon, descricao: dto.contaPoupanca.descricao } : undefined,
      user: dto.user ? { id: dto.user.id, nome: dto.user.nome, icon: dto.user.icon, descricao: dto.user.descricao } : undefined,
      userId: dto.userId ?? dto.user?.id
    };
  }

  /**
   * Map an array of DTOs to UI models
   */
  static toModelArray(dtos: TransacoesDTO[]): TransacaoModel[] {
    return dtos.map(d => this.toModel(d));
  }
}

import { UtilizadorDTO } from '../dto/utilizadores.dto';
import { UtilizadoresModel } from '../models/utilizadores.model';

/**
 * Mapper for Utilizadores - converts between API DTO and UI Model
 */
export class UtilizadoresMapper {
  static toModel(dto: UtilizadorDTO): UtilizadoresModel {
    return {
      id:       dto.userId,
      nome:     dto.name,
      email:    dto.email,
      role:     dto.role,
      isActive: dto.isActive ?? true,
    };
  }

  static toModelArray(dtos: UtilizadorDTO[]): UtilizadoresModel[] {
    return dtos.map(d => this.toModel(d));
  }
}

