.app-shell {
  display: flex;
  flex-direction: row;
  min-height: 100vh;
  width: 100%;
}

/* Sidebar esquerda fixa */
.sidebar {
  position: fixed;
  left: 0;
  top: 0;
  bottom: 0;
  width: var(--sidebar-width);
  background: #001528;
  display: flex;
  flex-direction: column;
  z-index: 1000;
  overflow-y: auto;
  overflow-x: hidden;
  border-right: 2px solid rgba(255, 255, 255, 0.2);
  box-shadow: 2px 0 8px rgba(0, 0, 0, 0.1);
}

/* Wrapper do conteúdo principal */
.main-wrapper {
  margin-left: var(--sidebar-width);
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  width: calc(100% - var(--sidebar-width));
}

/* Área de conteúdo */
.content {
  flex: 1;
  overflow: auto;
  padding: 2rem;
}

/* === MOBILE HAMBURGER === */
.hamburger {
  display: none;
  position: fixed;
  top: 0.75rem;
  left: 0.75rem;
  z-index: 1100;
  background: #0b253a;
  border: 1.5px solid rgba(97, 237, 214, 0.35);
  border-radius: 8px;
  padding: 0.45rem 0.55rem;
  cursor: pointer;
  flex-direction: column;
  gap: 5px;
  align-items: center;
  justify-content: center;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: #e2e8f0;
  border-radius: 2px;
  transition: background 0.2s;
}

.hamburger:hover span { background: #61edd6; }

/* === OVERLAY === */
.sidebar-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.55);
  z-index: 999;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
}

/* Responsivo - em telas pequenas, esconder sidebar ou fazer overlay */
@media (max-width: 768px) {
  .sidebar {
    width: var(--sidebar-width-tablet, 220px);
  }

  .main-wrapper {
    margin-left: var(--sidebar-width-tablet, 220px);
    width: calc(100% - var(--sidebar-width-tablet, 220px));
  }
}

@media (max-width: 600px) {
  /* Hide sidebar off-screen by default */
  .sidebar {
    transform: translateX(-100%);
    transition: transform 0.28s ease;
    width: 260px;
  }

  /* Slide in when open */
  .sidebar.open {
    transform: translateX(0);
  }

  /* Full width content */
  .main-wrapper {
    margin-left: 0;
    width: 100%;
  }

  /* Add top padding so content doesn't hide under hamburger */
  .content {
    padding: 3.5rem 1rem 1rem;
  }

  /* Show hamburger */
  .hamburger {
    display: flex;
  }

  /* Show overlay when sidebar is open */
  .sidebar-overlay {
    display: block;
  }

  .sidebar-overlay.visible {
    opacity: 1;
    pointer-events: auto;
  }
}

