:host {
  display: inline-block;
}

.app-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-weight: 600;
  border-radius: var(--radius-md, 8px);
  cursor: pointer;
  text-decoration: none;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  border: 1px solid transparent;
  user-select: none;
  white-space: nowrap;
}

/* Sizes */
.app-btn--small {
  padding: 6px 12px;
  font-size: 0.8125rem;
  line-height: 1.4;
}

.app-btn--medium {
  padding: 10px 18px;
  font-size: 0.9375rem;
  line-height: 1.5;
}

.app-btn--large {
  padding: 14px 24px;
  font-size: 1.0625rem;
  line-height: 1.5;
}

/* Variants */
.app-btn--primary {
  background: linear-gradient(135deg, var(--brand-accent) 0%, #4dd4c0 100%);
  color: #001528;
  box-shadow: 0 2px 8px rgba(97, 237, 214, 0.2);
}
.app-btn--primary:hover:not(:disabled):not(.app-btn--disabled) {
  background: linear-gradient(135deg, #4dd4c0 0%, #38b2ac 100%);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(97, 237, 214, 0.35);
}

.app-btn--secondary {
  background: transparent;
  color: var(--brand-text, #e2e8f0);
  border: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: none;
}
.app-btn--secondary:hover:not(:disabled):not(.app-btn--disabled) {
  background: rgba(255, 255, 255, 0.08);
  color: var(--brand-accent, #61edd6);
  border-color: var(--brand-accent, #61edd6);
  transform: translateY(-1px);
}

.app-btn--danger {
  background: #ff6b6b;
  color: #ffffff;
  border: none;
  box-shadow: 0 2px 8px rgba(255, 107, 107, 0.2);
}
.app-btn--danger:hover:not(:disabled):not(.app-btn--disabled) {
  background: #ff5252;
  color: #ffffff;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(255, 107, 107, 0.35);
}

.app-btn--outline {
  background: transparent;
  color: var(--color-primary, #2563eb);
  border-color: var(--color-primary, #2563eb);
}
.app-btn--outline:hover:not(:disabled):not(.app-btn--disabled) {
  background: rgba(37, 99, 235, 0.05);
}

/* Disabled state */
button:disabled,
.app-btn--disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none !important;
  box-shadow: none !important;
}

/* Spinner */
.btn-spinner {
  width: 16px;
  height: 16px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: spin 0.75s linear infinite;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

