:host {
  position: relative;
  width: 100%;
  flex: 1;
  display: flex;
  flex-direction: column;
  background: transparent;

  /* color variables for easy theming */
  --nav-bg: transparent;
  --nav-text: #e2e8f0;
  --nav-hover-bg: rgba(97,237,214,0.08);
  --nav-active-bg: rgba(97,237,214, 0.18);
  --nav-active-text: #61edd6;
  --nav-border: rgba(97,237,214, 0.18);

  /* sizing variables */
  --nav-font-size: 15px; /* larger link text */
  --nav-icon-size: 21px; /* larger icons */

  font-family: 'Archivo Black', 'Lavishly Yours', Georgia, serif;
  overflow-y: auto;
  box-sizing: border-box; /* ensure padding is included in width calculations */
}

.nav {
  display: flex;
  flex-direction: column;
  width: 100%;
  padding: 0;
  background: var(--nav-bg);
  box-sizing: border-box;
}

.nav-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  margin: 0;
  padding: 0.5rem;
  width: 100%;
  box-sizing: border-box;
}

.nav-item {
  position: relative;
  width: 100%;
}

.nav-link {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 12px 16px;
  border-radius: 6px;
  color: var(--nav-text);
  text-decoration: none;
  transition: background .12s ease, transform .08s ease;
  font-family: inherit;
  cursor: pointer;
  font-size: var(--nav-font-size);
  /* let flex sizing handle width; avoid forcing 100% which plus padding can overflow */
  width: auto;
  text-align: left;
  border-left: 3px solid transparent; /* accent when active */
  box-sizing: border-box;
}

/* Ensure icon occupies fixed space and label is vertically centered */
.nav-icon {
  flex: 0 0 var(--nav-icon-size); /* fixed width/height area */
  width: var(--nav-icon-size);
  height: var(--nav-icon-size);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  vertical-align: middle;
}

/* actual img inside wrapper */
.nav-icon-img {
  max-width: 100%;
  max-height: 100%;
  display: block;
  object-fit: contain;
  filter: brightness(0) invert(1); /* default white */
}

.nav-label {
  flex: 1 1 auto;
  display: inline-flex;
  align-items: center; /* vertically center label with icon */
  height: var(--nav-icon-size);
  line-height: 1;
}

.nav-link:hover,
.nav-link.active,
.nav-link[aria-current="page"],
.nav-link:active,
.nav-link:focus {
  background: var(--nav-active-bg);
  color: var(--nav-active-text);
  border-left-color: var(--nav-border);
  outline: none;
}

.nav-link:hover .nav-icon-img,
.nav-link.active .nav-icon-img,
.nav-link[aria-current="page"] .nav-icon-img,
.nav-link:active .nav-icon-img,
.nav-link:focus .nav-icon-img {
  /* tint approximating --nav-active-text */
  filter: invert(97%) sepia(67%) saturate(2545%) hue-rotate(145deg) brightness(107%) contrast(86%);
}

/* === RESPONSIVE ADJUSTMENTS === */
@media (max-width: 768px) {
  .nav-link {
    padding: 10px 14px;
    font-size: calc(var(--nav-font-size) - 2px);
  }

  .nav-icon {
    width: calc(var(--nav-icon-size) - 6px);
    height: calc(var(--nav-icon-size) - 6px);
  }
}

@media (max-width: 480px) {
  .nav-link {
    padding: 8px 12px;
    font-size: calc(var(--nav-font-size) - 4px);
  }

  .nav-icon {
    width: calc(var(--nav-icon-size) - 8px);
    height: calc(var(--nav-icon-size) - 8px);
  }
}

