})
export class SemValorSectionComponent {
  /**
   * Rótulo ou título da secção de alerta.
   */
  @Input({ required: true }) label = '';

  /**
   * Lista de despesas recorrentes que não possuem valor financeiro registado (`temValor: false`).
   */
